cd /work && python3 - <<'EOF'
import re, pathlib
allowed = {  # article numbers permitted by library/INDEX.md
 "7","8","9","10","41","45","49","52","55","58","59","6","189","224"
}
pat = re.compile(r"arts?\.?\s+([0-9]+)")
found = {}
for p in pathlib.Path("deliverable").glob("*"):
    txt = p.read_text()
    for m in pat.finditer(txt):
        found.setdefault(m.group(1), set()).add(p.name)
    # also check named non-LRF sources
    for token in ("LC 123", "Tema 1.051", "Tema 885", "1.333.349", "Súmula 581", "CPC", "1.871.201"):
        if token in txt:
            found.setdefault("["+token+"]", set()).add(p.name)
for k in sorted(found, key=lambda x:(not x.isdigit(), x)):
    flag = "OK " if (not k.isdigit() or k in allowed) else "!!!"
    print(flag, k, "->", sorted(found[k]))
EOF

